// Synthetic workbooks with drawings and comments, generated by code: the
// worksheet is built by buildXlsx() and the parts around it (drawing, media,
// comments, legacy drawing, threaded comments, persons) are added to the
// package the way Excel lays them out.

import { ZipArchive } from '../src/zip';
import { buildXlsx, utf8, worksheetXml } from './fixtures';

const XML = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>';
const NS_REL = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships';
const NS_PKG_REL = 'http://schemas.openxmlformats.org/package/2006/relationships';
const NS_XDR = 'http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing';
const NS_A = 'http://schemas.openxmlformats.org/drawingml/2006/main';
const NS_MAIN = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main';

export const PX = 9525;

export const THEME =
  `${XML}<a:theme xmlns:a="${NS_A}" name="Office"><a:themeElements><a:clrScheme name="Office">` +
  '<a:dk1><a:sysClr val="windowText" lastClr="000000"/></a:dk1><a:lt1><a:sysClr val="window" lastClr="FFFFFF"/></a:lt1>' +
  '<a:dk2><a:srgbClr val="44546A"/></a:dk2><a:lt2><a:srgbClr val="E7E6E6"/></a:lt2>' +
  '<a:accent1><a:srgbClr val="4472C4"/></a:accent1><a:accent2><a:srgbClr val="ED7D31"/></a:accent2>' +
  '<a:accent3><a:srgbClr val="A5A5A5"/></a:accent3><a:accent4><a:srgbClr val="FFC000"/></a:accent4>' +
  '<a:accent5><a:srgbClr val="5B9BD5"/></a:accent5><a:accent6><a:srgbClr val="70AD47"/></a:accent6>' +
  '<a:hlink><a:srgbClr val="0563C1"/></a:hlink><a:folHlink><a:srgbClr val="954F72"/></a:folHlink>' +
  '</a:clrScheme></a:themeElements></a:theme>';

/** A corner of an anchor; offsets in pixels. */
export const marker = (name: 'from' | 'to', col: number, row: number, colOff = 0, rowOff = 0) =>
  `<xdr:${name}><xdr:col>${col}</xdr:col><xdr:colOff>${colOff * PX}</xdr:colOff><xdr:row>${row}</xdr:row><xdr:rowOff>${rowOff * PX}</xdr:rowOff></xdr:${name}>`;

export const twoCell = (from: [number, number, number?, number?], to: [number, number, number?, number?], inner: string, editAs?: string) =>
  `<xdr:twoCellAnchor${editAs ? ` editAs="${editAs}"` : ''}>${marker('from', from[0], from[1], from[2], from[3])}${marker('to', to[0], to[1], to[2], to[3])}${inner}<xdr:clientData/></xdr:twoCellAnchor>`;

/** Size in pixels. */
export const oneCell = (from: [number, number, number?, number?], width: number, height: number, inner: string) =>
  `<xdr:oneCellAnchor>${marker('from', from[0], from[1], from[2], from[3])}<xdr:ext cx="${width * PX}" cy="${height * PX}"/>${inner}<xdr:clientData/></xdr:oneCellAnchor>`;

/** Position and size in pixels. */
export const absolute = (x: number, y: number, width: number, height: number, inner: string) =>
  `<xdr:absoluteAnchor><xdr:pos x="${x * PX}" y="${y * PX}"/><xdr:ext cx="${width * PX}" cy="${height * PX}"/>${inner}<xdr:clientData/></xdr:absoluteAnchor>`;

/** `fill` is the inner XML of <xdr:blipFill> after the blip (a:srcRect, a:stretch); `xfrm` are attributes of <a:xfrm>. */
export const pic = (rel: string, options: { name?: string; descr?: string; fill?: string; xfrm?: string; link?: boolean; nv?: string } = {}) =>
  `<xdr:pic><xdr:nvPicPr><xdr:cNvPr id="2" name="${options.name ?? 'Picture 1'}"${options.descr ? ` descr="${options.descr}"` : ''}>${options.nv ?? ''}</xdr:cNvPr><xdr:cNvPicPr/></xdr:nvPicPr>` +
  `<xdr:blipFill><a:blip xmlns:r="${NS_REL}" r:${options.link ? 'link' : 'embed'}="${rel}"/>${options.fill ?? '<a:stretch><a:fillRect/></a:stretch>'}</xdr:blipFill>` +
  `<xdr:spPr><a:xfrm${options.xfrm ? ` ${options.xfrm}` : ''}><a:off x="0" y="0"/><a:ext cx="0" cy="0"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></xdr:spPr></xdr:pic>`;

/** `props` is the inner XML of <xdr:spPr> after the geometry; `body` the whole <xdr:txBody>; `xfrm` the whole <a:xfrm>. */
export const sp = (options: { prst?: string; props?: string; body?: string; style?: string; xfrm?: string; name?: string } = {}) =>
  `<xdr:sp><xdr:nvSpPr><xdr:cNvPr id="3" name="${options.name ?? 'Shape 1'}"/><xdr:cNvSpPr/></xdr:nvSpPr>` +
  `<xdr:spPr>${options.xfrm ?? ''}<a:prstGeom prst="${options.prst ?? 'rect'}"><a:avLst/></a:prstGeom>${options.props ?? ''}</xdr:spPr>${options.style ?? ''}${options.body ?? ''}</xdr:sp>`;

export const solid = (rgb: string) => `<a:solidFill><a:srgbClr val="${rgb}"/></a:solidFill>`;

/** Width in pixels. */
export const outline = (rgb: string, width = 1, extra = '') => `<a:ln w="${Math.round(width * PX)}">${solid(rgb)}${extra}</a:ln>`;

export const run = (text: string, props = '', inner = '') => `<a:r><a:rPr lang="en-US"${props ? ` ${props}` : ''}>${inner}</a:rPr><a:t>${text}</a:t></a:r>`;

export const para = (inner: string, props = '') => `<a:p>${props}${inner}</a:p>`;

export const txBody = (paragraphs: string, bodyPr = '<a:bodyPr/>') => `<xdr:txBody>${bodyPr}<a:lstStyle/>${paragraphs}</xdr:txBody>`;

export const xfrm = (x: number, y: number, width: number, height: number, attrs = '', child?: [number, number, number, number]) =>
  `<a:xfrm${attrs ? ` ${attrs}` : ''}><a:off x="${x}" y="${y}"/><a:ext cx="${width}" cy="${height}"/>` +
  `${child ? `<a:chOff x="${child[0]}" y="${child[1]}"/><a:chExt cx="${child[2]}" cy="${child[3]}"/>` : ''}</a:xfrm>`;

export const group = (transform: string, members: string) =>
  `<xdr:grpSp><xdr:nvGrpSpPr><xdr:cNvPr id="9" name="Group 1"/><xdr:cNvGrpSpPr/></xdr:nvGrpSpPr><xdr:grpSpPr>${transform}</xdr:grpSpPr>${members}</xdr:grpSp>`;

export const connector = (props: string, transform = '') =>
  `<xdr:cxnSp><xdr:nvCxnSpPr><xdr:cNvPr id="5" name="Connector 1"/><xdr:cNvCxnSpPr/></xdr:nvCxnSpPr><xdr:spPr>${transform}<a:prstGeom prst="line"><a:avLst/></a:prstGeom>${props}</xdr:spPr></xdr:cxnSp>`;

export const chartFrame = (uri = 'http://schemas.openxmlformats.org/drawingml/2006/chart') =>
  `<xdr:graphicFrame><xdr:nvGraphicFramePr><xdr:cNvPr id="7" name="Chart 1"/><xdr:cNvGraphicFramePr/></xdr:nvGraphicFramePr><xdr:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/></xdr:xfrm>` +
  `<a:graphic><a:graphicData uri="${uri}"/></a:graphic></xdr:graphicFrame>`;

export const drawingXml = (inner: string) =>
  `${XML}<xdr:wsDr xmlns:xdr="${NS_XDR}" xmlns:a="${NS_A}" xmlns:mc="http://schemas.openxmlformats.org/markup-compatibility/2006">${inner}</xdr:wsDr>`;

/** Legacy comments part; `comments` is the inner XML of <commentList>. */
export const commentsXml = (authors: string[], comments: string) =>
  `${XML}<comments xmlns="${NS_MAIN}"><authors>${authors.map((author) => `<author>${author}</author>`).join('')}</authors><commentList>${comments}</commentList></comments>`;

export const comment = (ref: string, authorId: number, text: string) => `<comment ref="${ref}" authorId="${authorId}"><text>${text}</text></comment>`;

/** One comment box of a legacy drawing; `anchor` is the text of <x:Anchor>. */
export const vmlNote = (row: number, col: number, options: { anchor?: string; visible?: boolean } = {}) =>
  `<v:shape id="_x0000_s${1025 + row * 100 + col}" type="#_x0000_t202" style="position:absolute;visibility:${options.visible ? 'visible' : 'hidden'}" fillcolor="#ffffe1" o:insetmode="auto">` +
  '<v:fill color2="#ffffe1"/><v:shadow on="t" color="black" obscured="t"/><v:path o:connecttype="none"/><v:textbox style="mso-direction-alt:auto"><div style="text-align:left"></div></v:textbox>' +
  `<x:ClientData ObjectType="Note"><x:MoveWithCells/><x:SizeWithCells/><x:Anchor>${options.anchor ?? `${col + 1}, 15, ${Math.max(row - 1, 0)}, 2, ${col + 3}, 15, ${row + 3}, 16`}</x:Anchor>` +
  `<x:AutoFill>False</x:AutoFill><x:Row>${row}</x:Row><x:Column>${col}</x:Column>${options.visible ? '<x:Visible/>' : ''}</x:ClientData></v:shape>`;

export const vmlXml = (shapes: string) =>
  '<xml xmlns:v="urn:schemas-microsoft-com:vml" xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel">' +
  '<o:shapelayout v:ext="edit"><o:idmap v:ext="edit" data="1"/></o:shapelayout>' +
  '<v:shapetype id="_x0000_t202" coordsize="21600,21600" o:spt="202" path="m,l,21600r21600,l21600,xe"><v:stroke joinstyle="miter"/><v:path gradientshapeok="t" o:connecttype="rect"/></v:shapetype>' +
  `${shapes}</xml>`;

export interface DrawingBookSpec {
  /** Inner XML of the worksheet before the references to the drawing parts (sheetData, cols, sheetViews, ...). */
  sheet?: string;
  /** Inner XML of the drawing part (anchors). */
  drawing?: string;
  /** Pictures of the drawing: relationship id -> bytes; the part is named after the id. */
  media?: Record<string, Uint8Array>;
  /** Further relationships of the drawing part, as XML. */
  drawingRels?: string;
  /** Complete comments part. */
  comments?: string;
  /** Complete legacy drawing part. */
  vml?: string;
  /** Complete threaded comments part. */
  threaded?: string;
  /** Complete persons part. */
  persons?: string;
  /** Complete XML for a part given by name, for whatever else a test needs. */
  extra?: Record<string, string | Uint8Array>;
  /** Leave the theme out. */
  noTheme?: boolean;
}

/** A workbook with one sheet ("Sayfa1") and the given parts around it. */
export async function drawingWorkbook(spec: DrawingBookSpec): Promise<Uint8Array> {
  const refs = (spec.drawing !== undefined ? '<drawing r:id="rIdD"/>' : '') + (spec.vml !== undefined ? '<legacyDrawing r:id="rIdV"/>' : '');
  const bytes = await buildXlsx({
    theme: spec.noTheme ? undefined : THEME,
    sheets: [{ name: 'Sayfa1', xml: worksheetXml((spec.sheet ?? '<sheetData/>') + refs) }],
  });
  const zip = ZipArchive.read(bytes);
  const sheetRels: string[] = [];
  if (spec.drawing !== undefined) {
    sheetRels.push(`<Relationship Id="rIdD" Type="${NS_REL}/drawing" Target="../drawings/drawing1.xml"/>`);
    zip.set('xl/drawings/drawing1.xml', utf8(drawingXml(spec.drawing)));
    const rels: string[] = [];
    for (const [id, data] of Object.entries(spec.media ?? {})) {
      rels.push(`<Relationship Id="${id}" Type="${NS_REL}/image" Target="../media/${id}.bin"/>`);
      zip.set(`xl/media/${id}.bin`, data);
    }
    if (rels.length > 0 || spec.drawingRels) {
      zip.set('xl/drawings/_rels/drawing1.xml.rels', utf8(`${XML}<Relationships xmlns="${NS_PKG_REL}">${rels.join('')}${spec.drawingRels ?? ''}</Relationships>`));
    }
  }
  if (spec.comments !== undefined) {
    sheetRels.push(`<Relationship Id="rIdC" Type="${NS_REL}/comments" Target="../comments1.xml"/>`);
    zip.set('xl/comments1.xml', utf8(spec.comments));
  }
  if (spec.vml !== undefined) {
    sheetRels.push(`<Relationship Id="rIdV" Type="${NS_REL}/vmlDrawing" Target="../drawings/vmlDrawing1.vml"/>`);
    zip.set('xl/drawings/vmlDrawing1.vml', utf8(spec.vml));
  }
  if (spec.threaded !== undefined) {
    sheetRels.push('<Relationship Id="rIdT" Type="http://schemas.microsoft.com/office/2017/10/relationships/threadedComment" Target="../threadedComments/threadedComment1.xml"/>');
    zip.set('xl/threadedComments/threadedComment1.xml', utf8(spec.threaded));
  }
  if (spec.persons !== undefined) {
    const name = 'xl/_rels/workbook.xml.rels';
    const rels = new TextDecoder().decode(await zip.read(name));
    zip.set(
      name,
      utf8(rels.replace('</Relationships>', '<Relationship Id="rIdP" Type="http://schemas.microsoft.com/office/2017/10/relationships/person" Target="persons/person.xml"/></Relationships>')),
    );
    zip.set('xl/persons/person.xml', utf8(spec.persons));
  }
  if (sheetRels.length > 0) zip.set('xl/worksheets/_rels/sheet1.xml.rels', utf8(`${XML}<Relationships xmlns="${NS_PKG_REL}">${sheetRels.join('')}</Relationships>`));
  for (const [name, data] of Object.entries(spec.extra ?? {})) zip.set(name, typeof data === 'string' ? utf8(data) : data);
  return zip.write();
}
